const FIRST_RUN_KEY='jiedu.firstRunGuide.completed.v1.';
function firstRunSourceSummary(status,clientStatus){
  const sources=status?.sources||[],codex=sources.find(x=>x.id==='codex'),hermes=sources.find(x=>x.id==='hermes');
  const clients=clientStatus?.clients||[],codexClient=clients.find(x=>x.id==='codex'),hermesClient=clients.find(x=>x.id==='hermes');
  const codexFound=codexClient?.installed===true||(codexClient?.installed==null&&codex?.detected),hermesFound=hermesClient?.installed===true||(hermesClient?.installed==null&&hermes?.detected);
  const found=[codexFound?'ChatGPT 工作（Codex）':null,hermesFound?'Hermes':null].filter(Boolean);
  const label=found.length===2?'两种客户端均已发现，请分别配置':found.length===1?`仅发现 ${found[0]}，只配置该客户端`:'未发现 Codex 或 Hermes；先说明安装或来源状态，不创建假连接';
  const configured=[[codex,codexClient,codexFound,'Codex'],[hermes,hermesClient,hermesFound,'Hermes']].filter(row=>row[2]).map(([source,client,,name])=>`${name}：${client?client.configured?'MCP 已配置，仍需实测读取':'MCP 未配置':'MCP 配置待核验'}；后台归档${source?source.configured?'已开启':'未开启':'状态待核验'}`).join('；');
  return status||clientStatus?`${label}${configured?'。'+configured:''}`:'客户端状态暂不可读，请智能体在本机核对安装与现有配置';
}
function firstRunSourcePaths(status){
  const paths=(status?.sources||[]).filter(source=>['codex','hermes'].includes(source.id)).flatMap(source=>(source.locations||[]).filter(location=>location.detected&&location.readable).map(location=>`${source.id==='codex'?'Codex':'Hermes'} ${location.kind}：${location.path||location.root||''}`).filter(line=>!line.endsWith('：')));
  return paths.length?paths.join('；'):'当前接口未提供可分享的来源路径，请由界渡本机探测，不硬编码其他机器路径';
}
function firstRunPrompt(health,base,sources,clients){
  const workspace=base?.vault_path||health?.workspace_root||'尚未选定（请先引导我选择或连接工作区）';
  const endpoint=location.origin;
  return `请作为我的本机智能体，使用界渡产品已有的正式配置流程协助连接，并逐项报告真实结果。不要在我的电脑上改界渡源码、打补丁、重新构建或反复排障。若发现产品版本缺陷，只记录简短的无密钥错误和复现步骤，停止受影响步骤并交给开发处理。以下只包含可分享的本机位置，不包含配对密钥或知识正文。\n\n本机界渡控制台：${endpoint}\n当前工作区：${workspace}\n工作区 ID：${health?.workspace_id||'尚未建立'}\n本机来源初步检测：${firstRunSourceSummary(sources,clients)}\n本机已发现来源路径：${firstRunSourcePaths(sources)}\n界渡安装目录：${health?.program_root||health?.installation_path||'未由接口提供，请核对本机运行中进程/启动器的实际位置'}。不要根据本提示词猜测，也不要把工作区误当成安装目录。\n\n1. 自动检测本机是否安装 ChatGPT 工作（Codex）和 Hermes。只检测到 Hermes 就仅配置 Hermes；两者都存在就分别配置两者。不要把 ChatGPT 云端普通聊天当作本机 Codex 已受支持。若都未检测到，说明原因和下一步，不创建虚假的客户端。\n2. 核对界渡真实安装目录、控制台地址、工作区路径和工作区 ID。工作区未建立时，先让我在界渡选择或连接，不擅自新建或覆盖。仅通过正式流程配置实际安装的 AI 客户端，先备份原配置；不重置既有身份、配对、权限、归档游标或用户明确限制，不重复生成已有连接。需要配对秘密时通过界渡正式配对流程取得，切勿把秘密写进报告。\n3. 将已检测的客户端接入界渡 MCP，并做一次真实知识读取验证：读取已授权的本机资料或正式知识，记录成功或失败及原因。确认默认普通读取权限适用；受保护知识、删除、导出及正式知识写入须遵守原有限制。配置文件存在或复制提示词成功都不算验证成功。\n4. 检查当前工作区的检索索引状态；若缺失，仅使用界渡正式的建立索引操作并核对实际搜索结果。不要直接改动正式知识正文。\n5. 检查界渡后台自动归档：分别报告 Codex 与 Hermes 的历史补齐和新消息持续监听状态、已检查/已归档/失败缺失/排除范围。只处理本机可读且获授权的来源，保留旧资料、附件引用、已有游标及排除设置，不重新初始化或覆盖原始档案。AI 客户端 MCP 配置与界渡后台采集是两项独立工作，不把知识读取成功误报为聊天归档成功。\n6. 如果修改客户端配置需要重启 ChatGPT 工作（Codex）或 Hermes，明确告诉我需要重启哪个客户端，再在重启后复测真实 MCP 读取。最后逐项列出已完成、未完成、需要我决定的事项和证据。未经我确认，不自动修改正式知识。`;
}
async function showFirstRunGuide(health,{installedFresh=false}={}){
  const key=FIRST_RUN_KEY+(health.workspace_id||'unselected');
  if(!installedFresh)try{if(localStorage.getItem(key)==='1')return}catch{if(sessionStorage.getItem(key)==='1')return}
  const guide=$('#firstRunGuide'),prompt=$('#firstRunPrompt'),state=$('#firstRunCopyState'),enter=$('#firstRunEnter'),manual=$('#firstRunManualWrap'),check=$('#firstRunManualConfirm');
  if(!guide)return;
  $('#firstRunCopy').disabled=true;$('#firstRunSelect').disabled=true;
  enter.disabled=true;manual.hidden=true;check.checked=false;state.textContent='复制后才能确认进入。复制只表示提示词已交付，配置是否生效仍需智能体实际核验。';
  $('#brandSequence')?.classList.add('done');guide.hidden=false;document.body.classList.add('first-run-open');$('.sidebar').inert=true;document.querySelector('body>main').inert=true;
  const [baseResult,sourceResult,clientResult]=await Promise.allSettled([api('/api/knowledge-base?t='+Date.now(),{ttl:0,force:true,scope:'health'}),api('/api/local-sources/status?t='+Date.now(),{ttl:0,force:true,scope:'health'}),api('/api/local-ai/status?t='+Date.now(),{ttl:0,force:true,scope:'health'})]);
  const base=baseResult.status==='fulfilled'?baseResult.value:null,sources=sourceResult.status==='fulfilled'?sourceResult.value:null,clients=clientResult.status==='fulfilled'?clientResult.value:null;
  const path=base?.vault_path||health.workspace_root||'尚未选定';
  $('#firstRunWorkspace').textContent=`本机工作区：${path}\n控制台：${location.origin}\n${firstRunSourceSummary(sources,clients)}`;
  prompt.value=firstRunPrompt(health,base,sources,clients);
  $('#firstRunCopy').disabled=false;$('#firstRunSelect').disabled=false;
  $('#firstRunCopy').onclick=async()=>{const ok=await copyText(prompt.value);if(ok){enter.disabled=false;manual.hidden=true;check.checked=false;state.textContent='提示词已复制。请交给智能体；进入界渡不代表配置已验证。'}else{manual.hidden=false;state.textContent='浏览器未能复制。点击“手动选择全文”，复制后勾选确认，即可进入。'}};
  $('#firstRunSelect').onclick=()=>{prompt.focus();prompt.select();manual.hidden=false;state.textContent='全文已选中。请按 Ctrl+C 手动复制，再勾选下方确认。'};
  check.onchange=()=>{if(check.checked)enter.disabled=false;else enter.disabled=true};
  enter.onclick=async()=>{if(enter.disabled)return;enter.disabled=true;let saved=true;if(installedFresh)try{await apiPost('/api/update-notice/onboarding-complete',{})}catch{saved=false;showToast('进入界渡；首次提示状态暂时未保存，下次启动会再提醒。')}if(saved)try{localStorage.setItem(key,'1')}catch{sessionStorage.setItem(key,'1')}guide.hidden=true;document.body.classList.remove('first-run-open');$('.sidebar').inert=false;document.querySelector('body>main').inert=false;$('#brandSequence')?.classList.add('done')};
  $('#firstRunCopy').focus({preventScroll:true});
}
