function switchPage(name){
  if(workspaceRuntime&&!workspaceRuntime.workspace_ready&&name!=='workspace'){name='workspace';showToast('请先初始化或连接工作区，再导入资料')}
  const alreadyActive=document.querySelector('.page.active');if(alreadyActive?.id===name&&alreadyActive.dataset.navigationReady==='true'){window.closeWorkspaceNavigation?.();return}
  navigationCleanup();const navigation=++pageNavigationSequence;
  if(name!=='butler')window.leaveButler?.();
  document.body.classList.toggle('butler-open',name==='butler');
  sessionStorage.setItem('jiedu.activePage',name);
  const outgoing=document.querySelector('.page.active')?.id||activePage;pageScrollState.set(outgoing,window.scrollY);
  if(outgoing!==name){clearPageFeedback(outgoing);abortPageRequests(outgoing)}
  document.querySelectorAll(`#${outgoing} details`).forEach((node,index)=>detailsState.set(`${outgoing}:${node.className}:${index}`,node.open));
  $$('.sidebar nav button,.page').forEach(x=>x.classList.remove('active'));
  $(`.sidebar nav button[data-page="${name}"]`)?.classList.add('active');$(`#${name}`)?.classList.add('active');
  activePage=name;$(`#${name}`).dataset.navigationReady='true';window.closeWorkspaceNavigation?.();
  let pageLoad=Promise.resolve();
  [$('#eyebrow').textContent,$('#title').textContent,$('#subtitle').textContent]=pages[name];
  if(name==='workspace')pageLoad=withPageFeedback('workspace','正在读取工作区…',()=>Promise.all([loadInitializationCenter(),loadKnowledgeBase()]));
  if(name==='overview')pageLoad=withPageFeedback('overview','正在读取首页…',()=>loadOverview());
  if(name==='map')loadMap();if(name==='graph')loadGraph();
  if(name==='ai-chat')loadBridgeStatus();
  if(name==='butler')window.loadButler?.();
  if(name==='memory')pageLoad=withPageFeedback('memory','正在读取整理中心…',()=>loadMemoryHubBounded());
  if(name==='wiki')pageLoad=loadKnowledgeWiki();
  if(name==='archives')pageLoad=loadArchivesHub();
  if(name==='files')pageLoad=withPageFeedback('files','正在读取知识资料…',()=>loadFiles());
  if(name==='protection'){loadProtectionStatus();loadAccessHub().catch(error=>console.error(error))}
  if(name==='access')pageLoad=withPageFeedback('access','正在读取 AI 连接…',()=>loadProtectionStatus({quiet:true}).then(()=>loadClientAccessControl()));
  if(name==='weight')pageLoad=withPageFeedback('weight','正在读取会话刷新状态…',()=>loadWeightHub().then(patchWeightProductCopy));
  const page=$(`#${name}`),originalDetails=new Set(page.querySelectorAll('details'));let userInteracted=false,initialScroll=null;
  const markInteraction=()=>{userInteracted=true};
  const recordToggle=event=>{if(!userInteracted||!originalDetails.has(event.target))return;const nodes=[...page.querySelectorAll('details')],index=nodes.indexOf(event.target);if(index>=0)detailsState.set(`${name}:${event.target.className}:${index}`,event.target.open)};
  for(const type of ['pointerdown','keydown','wheel'])document.addEventListener(type,markInteraction,{capture:true,passive:true});page.addEventListener('toggle',recordToggle,true);
  const cleanup=()=>{for(const type of ['pointerdown','keydown','wheel'])document.removeEventListener(type,markInteraction,true);page.removeEventListener('toggle',recordToggle,true)};navigationCleanup=cleanup;
  const restore=(afterLoad=false)=>{
    if(activePage!==name||navigation!==pageNavigationSequence)return;
    page.querySelectorAll('details').forEach((node,index)=>{if(afterLoad&&originalDetails.has(node))return;const key=`${name}:${node.className}:${index}`;if(detailsState.has(key))node.open=detailsState.get(key)});
    if(!afterLoad||(!userInteracted&&initialScroll!==null&&Math.abs(window.scrollY-initialScroll)<2))window.scrollTo({top:pageScrollState.get(name)||0,behavior:'instant'});
    if(!afterLoad)initialScroll=window.scrollY;if(name==='map')mapChart?.resize();if(name==='graph')graphChart?.resize();
  };
  requestAnimationFrame(()=>restore());Promise.resolve(pageLoad).then(()=>{if(activePage===name&&navigation===pageNavigationSequence)requestAnimationFrame(()=>{restore(true);cleanup()})},cleanup);

}
