function protectionMessage(error,fallback='操作未完成'){
  const raw=String(error?.message||'').trim();try{const parsed=JSON.parse(raw),detail=parsed.detail||parsed.message;if(typeof detail==='string')return detail;if(detail&&typeof detail==='object')return detail.message||detail.reason||detail.status||fallback;return parsed.error==='workspace_not_initialized'?'请先初始化或连接工作区，再导入资料':fallback}catch{return raw&&raw!=='[object Object]'?raw:fallback}
}
async function protectionPost(url,body={}){
  const response=await fetch(url,{method:'POST',headers:{'content-type':'application/json','x-jiedu-csrf':protectionCsrf},body:JSON.stringify(body)});
  if(!response.ok)throw Error(await response.text());
  return response.json();
}
let localSessionPromise=null,localSessionRetryAt=0;
async function readProtectionSession(){
  if(localSessionPromise)return localSessionPromise;
  localSessionPromise=(async()=>{
    let data=await api('/api/protection/status?t='+Date.now(),{ttl:0,force:true,scope:'protection-session'});
    if(data.storage_enabled!==false&&data.access_mode==='device'&&!data.owner_session_active&&Date.now()>=localSessionRetryAt){
      const response=await fetch('/api/protection/device-session',{method:'POST',headers:{'content-type':'application/json','x-jiedu-csrf':data.csrf_token},body:'{}'});
      if(response.ok){data=await response.json();localSessionRetryAt=0}else{localSessionRetryAt=Date.now()+10000;data.local_session_error='本机身份核验未完成，请确认使用当前 Windows 账户直接打开界渡。'}
    }
    return data;
  })();
  try{return await localSessionPromise}finally{localSessionPromise=null}
}
function renderDeviceProtection(data){
  const boundary=data.exit_recovery?'<p>旧密文保留。退出期间产生的普通副本请按上方提示核对。</p>':'<p>数据继续加密保存。设备托管依赖当前 Windows 账户；换电脑或账户时使用恢复密钥。无法防御控制同一账户或已解锁进程的程序。</p>';
  const recovery='<details class="recovery-unlock"><summary>改用恢复密钥完成迁移</summary><form id="unlockRecoveryForm" class="protection-form"><label>独立恢复密钥<textarea id="protectionRecoveryInput" rows="3" autocomplete="off" required></textarea></label><p id="protectionRecoveryError" role="alert"></p><button class="secondary" type="submit">恢复并托管到本机</button></form></details>';
  let body=`<div class="protection-step"><span>设备模式</span><h3>${data.owner_session_active?'当前 Windows 账户已确认':'正在确认本机身份'}</h3><p>日常浏览、连接管理和知识审核无需应用口令。刷新或正常重启后会自动核验本机身份。</p></div>`;
  if(data.local_session_error)body+=`<p role="alert">${esc(data.local_session_error)}</p>`;
  if(data.state==='locked')body+=`<section><h4>旧密文的一次迁移</h4><p>旧数据密钥尚未托管到 Windows。仅这一次需要旧口令或恢复密钥；完成后正常重启自动可读。普通管理已经可用。</p>${data.device_error?`<p role="alert">${esc(data.device_error)}</p>`:''}<form id="unlockProtectionForm" class="protection-form"><label>旧口令<input id="protectionPassphrase" type="password" autocomplete="current-password" required></label><p id="protectionFormError" role="alert"></p><button class="execute" type="submit">解密并完成设备托管</button></form>${recovery}</section>`;
  else if(data.state==='not_configured')body+='<p>尚未启用受保护存储，不影响普通知识和连接管理。</p><button id="initializeDevice" class="secondary" type="button">启用设备加密并生成恢复密钥</button>';
  else if(data.state==='unlocked')body+=`<p>受保护数据可用，共 ${data.protected_object_count??'—'} 个对象。${data.device_enrolled?'设备托管已验证。':'设备托管尚未完成。'}</p>${data.device_error?`<p role="alert">${esc(data.device_error)}</p><button id="enableDevice" class="secondary">重试设备托管</button>`:''}${protectionCancelMarkup(data)}<details><summary>可选：改为每次使用密码</summary><p>启用后，本机重新打开也需要密码或恢复密钥，不再自动解锁。</p><form id="manualModeForm" class="protection-form"><label>设置手动锁密码<input id="manualPassphrase" type="password" minlength="12" autocomplete="new-password" required></label><label>再次输入<input id="manualConfirmation" type="password" minlength="12" autocomplete="new-password" required></label><p id="manualModeError" role="alert"></p><button class="secondary" type="submit">改为密码解锁</button></form></details>`;
  else body+='<p role="alert">受保护存储需要修复。原密文保持不变，普通管理仍可使用。</p>';
  $('#protectionSummary').textContent='默认使用当前 Windows 账户，不再要求日常输入应用口令。';
  $('#protectionPanel').innerHTML=protectionShell(body+boundary);bindProtectionForms();
}
