function resetExpiredView(){const labels={reader:'从左侧选择资料查看正文。',fileList:'正在重新读取资料…',results:'输入关键词搜索资料。',rawSessionDetail:'选择一段对话查看档案。',knowledgeObjectDialogBody:'请重新打开资料。'};for(const [id,label] of Object.entries(labels)){const node=$('#'+id);if(node?.textContent==='访问会话已结束，请重新确认身份')node.textContent=label}}
function clearProtectedView(){knowledgeReadSequence++;invalidateGet();copyRegistry.clear();knowledgeObjectState=null;knowledgeObjectPreview=null;knowledgeObjectJob=null;memoryDocs=null;memoryCandidates=[];rawSessionView=null;for(const page of [...pageControllers.keys()])if(!['protection-session','health'].includes(page))abortPageRequests(page);for(const id of ['reader','fileList','results','rawSessionDetail','knowledgeObjectDialogBody']){const node=$('#'+id);if(node)node.textContent='访问会话已结束，请重新确认身份';}$('#knowledgeObjectDialog')?.close();}
setInterval(()=>{if(!document.hidden&&!protectionBusy)loadProtectionStatus({quiet:true})},5000);
