$('#editProfile').addEventListener('click',openProfile);$('#editProfileIcon').addEventListener('click',openProfile);
$('#profileForm').addEventListener('submit',e=>{e.preventDefault();if(e.submitter?.value==='cancel')return $('#profileDialog').close();const value=$('#username').value.trim()||defaultPrefs.username;prefs={...prefs,username:value};savePrefs();applyPrefs();$('#profileDialog').close();showToast('身份名称已保存')});
