function animateNumber(el,from,to){
  if(from===to||matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=to;return}
  const start=performance.now(),duration=420;const frame=now=>{const p=Math.min(1,(now-start)/duration),e=1-Math.pow(1-p,3);el.textContent=Math.round(from+(to-from)*e);if(p<1)requestAnimationFrame(frame)};requestAnimationFrame(frame)
}
function flashTelemetry(){
  const targets=[$('.system-status'),$('.instrument-stage'),$('.instrument-cluster'),$('.system-panel'),$('.layer-panel')];
  targets.forEach(x=>{x?.classList.remove('telemetry-changed');void x?.offsetWidth;x?.classList.add('telemetry-changed')});
  setTimeout(()=>targets.forEach(x=>x?.classList.remove('telemetry-changed')),760)
}
function renderLayers(files,changed){
  const layers={};files.forEach(f=>{const layer=f.source_path.split('/')[0]||'根目录';layers[layer]=(layers[layer]||0)+f.chunks});
  const max=Math.max(1,...Object.values(layers));
  $('#layerDistribution').innerHTML=Object.entries(layers).map(([k,v])=>`<div class="layer-row"><label title="${esc(k)}">${esc(k)}</label><div class="layer-track"><i data-width="${Math.max(3,v/max*100)}" style="width:${changed?0:Math.max(3,v/max*100)}%"></i></div><b>${v}</b></div>`).join('')||'<div class="empty compact"><p>暂无层级数据</p></div>';
  if(changed)requestAnimationFrame(()=>$$('#layerDistribution .layer-track i').forEach(x=>x.style.width=`${x.dataset.width}%`))
}
