  if($$('#metrics .metric').length!==cards.length)$('#metrics').innerHTML=cards.map((x,i)=>`<div class="metric metric-${x[3]}" data-key="${x[3]}"><div class="metric-signal" aria-hidden="true"><i></i></div><span>${x[0]}</span><strong>—</strong><small>${x[2]}</small><em></em></div>`).join('');
  cards.forEach(x=>{const el=$(`#metrics .metric[data-key="${x[3]}"] strong`);el.textContent=indexValue(x[1]);el.parentElement.querySelector('em').textContent=indexReady?x[4]:'等待建立知识检索'});
  const modelLabel=({loaded:'模型已加载',available_unloaded:'模型已缓存 · 首次查询时加载',load_failed:'模型加载失败',unavailable:'本机无完整模型'})[d.vector_model?.state]||'模型状态未知';
  $('#detail').innerHTML=`<div class="detail-grid"><label>知识库</label><span>${knowledgeConnected?'已连接':'未连接'}</span><label>本地路径</label><span class="technical">${esc(kb.vault_path||'尚未选择')}</span><label>本机资料</label><span>${workspaceReady?`${Number(workspaceIndex.file_count)||0} 份可搜索`:'索引未就绪'}</span><label>知识页资料</label><span>${ordinaryCount==null?'暂未读取':ordinaryCount+' 份'}</span><details class="home-diagnostics"><summary>这些数字表示什么？</summary><p>首页大数字优先显示本机资料可搜索段落；下方三张卡只统计正式知识。普通 Markdown 可在“本机资料”范围搜索，不会自动变成正式知识。</p></details><details class="home-diagnostics"><summary>检索诊断</summary><p>本机资料关键词索引：${workspaceReady?`${Number(workspaceIndex.chunk_count)||0} 段`:'未就绪'}；正式知识检索片段：${indexReady?d.chunk_count:'尚未建立'}；正式语义向量：${indexReady?d.vector_count:'尚未建立'}；${esc(modelLabel)}。</p></details></div>`;
