    series:[{type:'graph',layout:'force',roam:true,scaleLimit:{min:.35,max:4},draggable:true,selectedMode:false,edgeSymbol:['none','arrow'],edgeSymbolSize:[0,5],labelLayout:{hideOverlap:true},force:{initLayout:'none',repulsion:150,edgeLength:[105,155],gravity:.025,friction:.82,layoutAnimation:true},data:nodes,links,lineStyle:{color:'#718ca0'},emphasis:{focus:'adjacency',blurScope:'coordinateSystem',label:{show:true,color:'#fff'},lineStyle:{opacity:1,width:2}}}]
