function statusClass(value){return ['就绪','已启用','进行中'].includes(value)?'ready':['草稿'].includes(value)?'draft':['未启用','未就绪'].includes(value)?'offline':'neutral'}
let organizeReadEpoch=0;
const organizeLoads=new Map();
function organizeRead(url,epoch=organizeReadEpoch){const target=new URL(url,location.origin);target.searchParams.set('view_revision',String(epoch));return api(target.pathname+target.search,{ttl:0,force:true,scope:'organize-shared'})}
function onceOrganize(key,loader){const epoch=organizeReadEpoch,identity=epoch+':'+key;if(organizeLoads.has(identity))return organizeLoads.get(identity);const promise=Promise.resolve().then(()=>loader(epoch)).finally(()=>{if(organizeLoads.get(identity)===promise)organizeLoads.delete(identity)});organizeLoads.set(identity,promise);return promise}
function loadMemoryHub(){return onceOrganize('hub',async epoch=>{
  $('#organizeLoadState')?.remove();
  const sections=[['知识候选',loadMemoryCandidates],['原始来源',loadOriginalArchives],['提炼来源',loadManualExtraction],['持续更新',loadContinuousTasks]];
  const results=await Promise.allSettled(sections.map(([,loader])=>loader()));
  if(epoch!==organizeReadEpoch)return;
  const failed=results.map((result,index)=>result.status==='rejected'&&result.reason?.name!=='AbortError'?sections[index][0]:null).filter(Boolean);
  if(failed.length)throw Object.assign(Error(failed.join('、')+'读取失败；已显示的内容仍可查看，请重试。'),{partial:true});
})}
// The page indicator owns its timeout. Keep this promise alive so late success
// clears the warning instead of leaving a permanently rejected Promise.race.
function loadMemoryHubBounded(){return loadMemoryHub()}
let archiveProgressTimer=null;
function archiveProgressLine(history,title){
  const known=history.known_total==null?null:Math.max(0,Number(history.known_total)||0),checked=history.checked==null?null:Math.max(0,Number(history.checked)||0);
  const unit=history.unit==='files'?'份来源文件':'条来源记录',archivedUnit=history.unit==='files'?'条消息':'条记录';
  const count=value=>value==null?'待确认':Math.max(0,Number(value)||0);
  const percent=known>0&&checked!=null?Math.min(100,Math.floor(checked/known*100)):null;
  return `<div class="archive-progress-line"><label>${esc(title)} · 已检查 ${count(checked)} / ${known===null?'可读总量待确定':known} ${unit}${percent===null?'':` · 检查进度 ${percent}%`}${history.total_is_dynamic?' · 来源总量可能变化':''}${known===null?'<progress aria-label="历史检查进度，总量待确定"></progress>':`<progress max="${Math.max(known,1)}" value="${Math.min(checked||0,Math.max(known,1))}" aria-label="历史检查进度"></progress>`}</label><div class="archive-progress-counts"><span>已归档 <b>${count(history.archived)}</b> ${archivedUnit}</span><span>失败或来源缺失 <b>${count(history.failed_missing)}</b> ${unit}</span><span>排除 <b>${count(history.excluded)}</b> ${unit}</span><span>待核对 <b>${count(history.needs_review)}</b> ${unit}</span></div>${history.last_error?`<p role="status">最近错误：${esc(compactText(history.last_error,100))}</p>`:''}</div>`;
}
function archiveProgressCard(name,source){
  const history=source?.history||{},live=source?.live||{};
  const label={running:'正在补齐',watching:'持续监听',waiting:'等待首次同步',complete:'本批已检查',completed:'本批已检查',completed_with_review:'已检查，仍有待核对记录',paused:'已暂停',error:'需要检查',not_started:'尚未开始'};
  const parts=source?.detected===false?'':history.by_source?.length?history.by_source.map(row=>archiveProgressLine(row,row.source==='jsonl'?'会话日志':row.source?.startsWith('sqlite')?'SQLite 历史':'历史来源')).join(''):archiveProgressLine(history,'历史补齐');
  return `<article class="archive-progress-card"><div class="archive-progress-head"><h3>${name}</h3><span>${esc(label[history.status]||history.status||'状态待核对')}</span></div>${!source?.detected?'<p>本机尚未发现该来源。</p>':!source.readable?'<p>已发现来源，但暂不可读。</p>':''}${parts}${parts?'<p>百分比仅表示已检查来源的比例，不代表全部成功归档。</p>':''}${source?.last_error?`<p role="status">最近错误：${esc(compactText(source.last_error,100))}</p>`:''}<p>新消息监听：${esc(label[live.status]||live.status||'状态待核对')}${live.last_message_at?` · 最近消息 ${esc(formatTime(live.last_message_at))}`:''}${live.saved_messages!=null?` · 已保存 ${Number(live.saved_messages)||0} 条`:''}</p></article>`;
}
async function loadArchiveProgress(){
  const host=$('#archiveProgress');if(!host)return;clearTimeout(archiveProgressTimer);
  try{const status=await api('/api/local-sources/status?t='+Date.now(),{ttl:0,force:true});if(activePage!=='archives')return;const codex=status.sources?.find(x=>x.id==='codex')||status.codex,hermes=status.sources?.find(x=>x.id==='hermes')||status.hermes;host.innerHTML=`<div class="archive-progress-title"><div><h2>自动归档进度</h2><p>历史补齐与新消息监听分别计算。不同来源按自身单位显示，可读总量未知时不显示百分比；归档不等于正式知识。</p></div><button id="refreshArchiveProgress" type="button" class="copy-button">刷新进度</button></div><div class="archive-progress-grid">${archiveProgressCard('ChatGPT 工作（Codex）',codex)}${archiveProgressCard('Hermes',hermes)}</div><small>状态更新：${esc(formatTime(status.generated_at))}</small>`;host.querySelector('#refreshArchiveProgress').onclick=loadArchiveProgress}
  catch(error){if(!isRequestCancelled(error))host.innerHTML='<h2>自动归档进度</h2><p role="status">进度暂时无法读取。下方可查看各来源的详细状态。</p><button id="refreshArchiveProgress" type="button" class="copy-button">重试</button>';host.querySelector('#refreshArchiveProgress')?.addEventListener('click',loadArchiveProgress)}
  finally{if(activePage==='archives')archiveProgressTimer=setTimeout(loadArchiveProgress,5000)}
}
async function loadArchivesHub(){const list=$('#rawSessionList');if(list&&!list.children.length)list.innerHTML=loadingState('正在读取对话档案…');try{await Promise.all([loadRawSessions(),loadCodexArchiveStatus(),loadHermesArchiveStatus(),loadArchiveProgress()])}catch(e){if(isRequestCancelled(e))return;if(e.name==='AbortError')return;if(list){list.innerHTML=errorState(isIdentityError(e)?'本机读取身份失效':'对话档案暂时无法读取',e);list.querySelector('[data-async-retry]')?.addEventListener('click',loadArchivesHub)}showToast(protectionMessage(e,'对话档案读取失败'))}}
