function renderWeightSettings(w){const standard=[10,20,30,50].includes(w.turn_threshold);$('#weightCadence').textContent=`每 ${w.turn_threshold} 轮提醒一次`;$('#weightSettings').innerHTML=`<div class="cadence-panel"><div class="cadence-control"><span>每</span><input id="weightCustom" aria-label="提醒轮数" type="number" min="5" max="999" step="1" value="${w.turn_threshold}"><span>轮提醒一次</span></div><div class="cadence-presets">${[10,20,30,50].map(n=>`<button class="${w.turn_threshold===n?'active':''}" data-weight-preset="${n}">${n}</button>`).join('')}<button class="${standard?'':'active'}" data-weight-custom>自定义</button></div></div><div class="weight-switches">${weightSwitch('weightReminders','提醒我',w.reminders)}${weightSwitch('weightMemoryReminder','核心背景更新后提醒',w.memory_update_reminder)}${weightSwitch('weightAutomatic','自动权重提升',w.automatic)}<div class="owner-capability-note"><b>自动提升状态</b><br>${w.formal_core_enabled?'已配置':'已配置 · 等待正式核心背景'}</div></div>`;$$('[data-weight-preset]').forEach(b=>b.onclick=()=>{$('#weightCustom').value=b.dataset.weightPreset;saveWeightSettings()});$('[data-weight-custom]').onclick=()=>{$('#weightCustom').focus();$('#weightCustom').select()};$('#weightCustom').onchange=saveWeightSettings;$('#weightCustom').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();saveWeightSettings()}};['weightReminders','weightMemoryReminder','weightAutomatic'].forEach(id=>$('#'+id).onchange=async()=>{if(id==='weightAutomatic'&&$('#'+id).checked&&!confirm('开启自动权重提升需要Owner确认。正式核心背景未确认前只保存配置，不会执行注入。')){$('#'+id).checked=false;return}await saveWeightSettings()})}
