    const history=adapter.history||{},historyLabels={running:running?'正在导入历史':'已排队，等待采集器',paused:'历史导入已暂停',error:'历史导入需重试',complete:adapter.pending_projection_count?'源扫描完成 · 归档待处理':'源扫描完成'};
