    const historyHost=document.createElement('section');historyHost.className='hermes-history-panel';historyHost.innerHTML=`<h3>Hermes 历史对话</h3><p>${esc(historyLabels[history.status]||'尚未导入已有历史')} · ${running?'实时归档正在运行':adapter.last_error?'采集异常，请检查最近错误':!status.archive_enabled||adapter.status==='paused'?'实时归档已暂停':'尚未确认采集器运行；请查看最近同步时间'}。</p>${history.started_at?`<p>已检查 ${history.processed_rows||0} 条来源记录 / 启动时 ${history.source_rows_at_start||0} 条；包含内部记录，已排除 ${history.excluded_rows||0} 条，忽略内部/非活动记录 ${history.ignored_rows||0} 条；来源会话缺失 ${history.orphan_rows||0} 条，扫描时已消失 ${history.missing_rows||0} 条。${adapter.pending_projection_count?`仍有 ${adapter.pending_projection_count} 个会话等待归档投影。`:''}核对截止 ID ${history.upper_id||0}，不代表更早已删除的历史可恢复。</p>`:'<p>首次接入只监听新增消息。导入历史会只读扫描现存来源，保留正文、附件及原文件；不会自动提炼知识。</p>'}${history.last_error?`<p role="alert">${esc(history.last_error)}</p>`:''}<button type="button" id="hermesHistoryAction" class="copy-button">${history.status==='running'?'暂停历史导入':history.status==='paused'||history.status==='error'?'继续历史导入':'导入现存历史'}</button><button type="button" id="refreshHermesHistory" class="copy-button">刷新进度</button>`;box.append(historyHost);
    $('#hermesHistoryAction').onclick=async event=>{const action=history.status==='running'?'pause':history.status==='paused'||history.status==='error'?'resume':'start';if(action==='start'){openHermesHistoryConfirm(event.currentTarget);return}event.currentTarget.disabled=true;try{await apiPost('/api/hermes-archive/history',{action,owner_confirmed:true});await loadHermesArchiveStatus();showToast(action==='pause'?'历史导入已暂停，进度保留':'历史任务已恢复，可刷新查看进度')}catch(error){event.currentTarget.disabled=false;showToast(protectionMessage(error,'历史导入未开始'))}};
