function quickConnectPrompt(kind,health,outcome){
  const name=kind==='codex'?'Codex（ChatGPT 工作客户端）':'Hermes';
  const state=outcome==='paired'?'界渡刚刚保存了本机 MCP 配置和配对身份。':outcome==='existing_configuration'?'界渡发现原有客户端配置，未修改或重配。':'界渡已有此客户端连接，未修改原配置、身份或权限。';
  const root=health?.program_root||'接口未提供，请从本机运行中的界渡进程核对';
  const workspace=health?.workspace_root||'尚未加载，请先在界渡选择工作区';
  return `请在这台电脑的 ${name} 中完成界渡连接检查。只操作本机实际安装的软件，不把普通网页聊天当作有本机 MCP 权限的 Codex。\n\n本机界渡控制台：${location.origin}\n界渡当前运行目录：${root}\n当前工作区：${workspace}\n工作区 ID：${health?.workspace_id||'尚未加载'}\n连接起点：${state}\n\n1. 先核对上述目录和当前客户端确实属于这台电脑。不要采用任何开发者机器的路径。若工作区尚未加载、客户端未安装，或你没有本机文件与 MCP 能力，如实说明，停止配置，不声明已连接。\n2. 检查本客户端的界渡 MCP 工具。首次配置已由界渡正式配对事务写入并备份；已有配置只复用。不要读取、复制、打印或传递配置中的密钥，也不要新建第二个身份、轮换密钥、重置权限、索引、归档范围或同步游标。若配置还未被客户端加载，先使用客户端正规的 MCP 重新加载方式；必须重启时告诉我需要重启 ${name}，重启后继续本任务。不要关闭界渡或其他生产任务。\n3. 在本客户端真实调用界渡 MCP：先完成 initialize，再获取 tools/list，随后调用一个已授权的只读工具，读取普通本机资料或正式知识。只报告工具名称、成败、读取范围和不含知识正文的简短证据。initialize、工具清单、配置文件存在或复制成功都不算实际读取验证。若读取被拒绝，保留原权限并说明要由我在界渡决定，不擅自放宽。\n4. 回到界渡“AI连接”核对本客户端是否显示“已验证实际读取”。界渡后台自动归档与 MCP 读取分开判断；不要因为读取成功就声称历史聊天或新消息已归档。最后列出已完成、仍需重启或授权、未完成的步骤。`;
}
function renderQuickConnect(){
  const host=$('#quickConnectCards');if(!host)return;
  host.innerHTML=['codex','hermes'].map(kind=>{const state=quickConnectionState(kind),name=kind==='codex'?'Codex':'Hermes',note=kind==='codex'?'用于电脑上的 Codex / ChatGPT 工作客户端。网页聊天不支持此接入方式。':'适用于这台电脑上安装的 Hermes。';return `<article class="quick-connect-card"><div><h4>${name}</h4><span class="identity-status">${esc(state.label)}</span><p>${note}</p></div><button type="button" class="primary" data-quick-client="${kind}">${state.existing?'复制验证提示词':`复制并接入 ${name}`}</button></article>`}).join('');
  host.querySelectorAll('[data-quick-client]').forEach(button=>button.onclick=async()=>{
    const kind=button.dataset.quickClient,state=quickConnectionState(kind),feedback=$('#quickConnectFeedback');button.disabled=true;feedback.textContent=state.existing?'正在准备验证提示词…':'正在确认本机客户端并保存连接配置…';
    try{
      const health=await api('/api/health?t='+Date.now(),{ttl:0,force:true});
      if(!health.workspace_ready)throw Error('界渡工作区尚未加载，请先选择工作区并完成加载。');
      const result=state.existing?{outcome:state.legacy?'existing_configuration':'reused'}:await clientAccessPost('/api/client-access/quick-connect/'+kind,{});
      const prompt=quickConnectPrompt(kind,health,result.outcome),copied=await copyText(prompt);
      $('#quickConnectPrompt').textContent=prompt;$('#quickConnectFallback').hidden=copied;
      feedback.textContent=(copied?(result.outcome==='paired'?'配置已保存并备份。请把提示词交给客户端，完成重新加载和真实读取验证。':'已复制验证提示词；原连接和权限保持不变。'):'连接状态已保存；请展开下方提示词手动复制。')+(result.collection_warning?' '+result.collection_warning:'');
      await loadClientAccessControl({quiet:true});
    }catch(error){if(!isRequestCancelled(error))feedback.textContent=protectionMessage(error,'接入未完成；原配置保持不变');button.disabled=false}
  });
}
