const CLIENT_READ_CHECK_PROMPT='请检查当前客户端是否已经连接界渡：只使用实际可用的界渡工具，不读取或展示配置文件、环境变量、密钥或配对秘密。先核验连接身份，再在已允许的正式知识范围内搜索“界渡”，最多返回3条标题和来源路径；如果允许读取，打开其中1条并给出一句基于原文的摘要。工具不存在、认证失败、权限不足或没有结果时，请如实说明具体是哪一步未完成，提示我检查连接或重新打开客户端后再试，不要声称读过内容。不要改配置、增加权限、写入知识、提交整理建议或保存聊天。此次只读检查不代表自动归档已验证。';
function connectionCheckGuide(pending=false){const steps=`<ol><li>先确认并保存连接配置。</li><li>保存成功后，在客户端重新连接 MCP。Hermes 请先保存当前任务，完整退出软件后重新打开，再进入新对话；界渡不会替你关闭任务。</li><li>重连完成后，在客户端发送连接检查提示词，再返回界渡查看实际读取状态。</li></ol>`;if(pending)return `<section class="session-read-panel connection-check-guide"><h3>保存后怎么做</h3>${steps}<p>当前只是预览，请先点击底部确认。保存成功后才提供检查提示词；现在无需发送验证请求。</p></section>`;return `<section class="session-read-panel connection-check-guide"><h3>配置保存 → 客户端重连 → 验证读取</h3>${steps}<p>配置保存成功只表示准备完成。若工具不可用，请先检查 MCP 是否启用并重新连接。这段提示词不包含配对秘密，只检查允许范围内的读取，不验证自动归档。</p><pre class="selectable">${esc(CLIENT_READ_CHECK_PROMPT)}</pre><button type="button" class="secondary" data-copy-connection-check>复制连接检查提示词</button></section>`}

document.addEventListener('click',async event=>{const button=event.target.closest?.('[data-copy-connection-check]');if(button)button.textContent=await copyText(CLIENT_READ_CHECK_PROMPT)?'已复制检查提示词':'复制未完成，请重试'});
