function candidateStatusText(x){
  if(x.status==='reorganized')return '已更新 · 历史建议';
  if(x.status==='pending')return '待审核';
  if(x.status==='approved_staging')return x.write_reverted_at?'已撤销写入':'历史暂存 · 待写入';
  if(x.status==='written')return '已写入';
  if(x.status==='less_often')return '以后少提';
  return '已拒绝 · 未写入';
}
function candidateRenewalLabel(c){const state=c.reorganization_state;return state?.status==='needs_attention'?'需处理：'+(state.failure||'来源或权限暂不可用'):state?.status==='running'?'已领取 · 等待整理结果':'等待下次整理更新'}
function candidateGroups(rows){
  return {pending:rows.filter(x=>x.status==='pending'),staging:rows.filter(x=>x.status==='approved_staging'),written:rows.filter(x=>x.status==='written'),rejected:rows.filter(x=>x.status==='rejected'||x.status==='less_often')};
}
function candidateDisplayGroups(rows){
  const seen=new Set(),groups=new Map();
  for(const x of rows){if(seen.has(x.candidate_id))continue;seen.add(x.candidate_id);
    const p=x.provenance||{},c=p.continuity||{},target=String(p.target_path||'').replace(/\\/g,'/'),parts=target.split('/');
    const targetProject=parts[0]==='02_项目'&&parts.length>2&&parts[1]&&!parts.includes('..')?parts[1]:'';
    const project=targetProject||c.project||x.project||p.project||'',label=project||(parts.at(-1)||'待确定目标').replace(/\.md$/i,'');
    const groupKey=JSON.stringify(project?['project',project]:['target',target]);if(!groups.has(groupKey))groups.set(groupKey,{project,label,targets:new Set(),items:new Map()});groups.get(groupKey).targets.add(target);
    const key=c.merge_key?JSON.stringify(['merge',target,c.merge_key,x.status]):JSON.stringify(['candidate',x.candidate_id]);
    const items=groups.get(groupKey).items;if(!items.has(key))items.set(key,{key,records:[]});items.get(key).records.push(x);
  }
  return [...groups.values()].map(g=>({...g,targets:[...g.targets],items:[...g.items.values()]}));
}
function candidateRoleLabels(candidate){const labels={user_decision:'用户决定',plan:'计划',planner_restatement:'计划复述',independent_verification:'独立验证声明',execution_report:'执行报告',accepted:'验收声明（非独立验证）'};return [...new Set((candidate.provenance?.continuity?.source_roles||[]).map(x=>labels[x.kind]||x.kind).filter(Boolean))]}
function candidateBodyText(content){return String(content||'').replace(/^\uFEFF/,'').replace(/^---\s*\r?\n[\s\S]*?\r?\n(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/,'')}
function candidateExcerpt(content,limit=160){
  const plain=candidateBodyText(content).split(/\r?\n/).filter(line=>!/^\s{0,3}(?:#{1,6}\s|```|~~~|[-*_=]{3,}\s*$)/.test(line)&&!/^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line))
    .map(line=>line.replace(/^\s{0,3}(?:>\s?)+/,'').replace(/^\s*(?:[-+*]|\d+[.)])\s+(?:\[[ xX]\]\s*)?/,'')).join(' ')
    .replace(/!\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g,(_,path,label)=>label||path)
    .replace(/(\*\*|__|~~)(\S(?:.*?\S)?)\1/g,'$2').replace(/(^|\s)[*_]([^*_]+)[*_](?=\s|[，。！？,.!?]|$)/g,'$1$2').replace(/`([^`]+)`/g,'$1').replace(/\s+/g,' ').trim();
  return plain.length>limit?plain.slice(0,limit)+'…':plain;
}
function candidateIdentity(c){const group=candidateDisplayGroups([c])[0];return {key:JSON.stringify(group.project?['project',group.project]:['target',group.targets[0]]),label:group.label,project:group.project}}
function candidateReadableTitle(c){const path=String(c.provenance?.target_path||'').replace(/\\/g,'/'),file=path.split('/').pop();return file?file.replace(/\.md$/i,''):candidateBodyText(c.content).match(/^#\s+(.+)$/m)?.[1]||c.title||'尚未确定保存位置'}
