async function generateManualPackage(force){try{const session_ids=[...selectedExtractionSessions];if(!session_ids.length)throw Error('请先选择要提炼的会话');const d=await apiPost('/api/memory/manual-extraction/packages',{force,session_ids});const link=document.createElement('a');link.href=`/api/memory/manual-extraction/packages/${encodeURIComponent(d.package_id)}/download`;link.download='';document.body.append(link);link.click();link.remove();showToast('提炼包已生成并开始下载');await loadManualExtraction()}catch(e){if(isRequestCancelled(e))return;showToast(e.message||'提炼包生成失败')}}
async function changeExtractionSessionState(sessionId,state){
  try{
    await apiPost('/api/memory/manual-extraction/sessions/'+encodeURIComponent(sessionId)+'/state',{state});
    if(state==='deferred')selectedExtractionSessions.delete(sessionId);
    manualExtractionSignature='';
    await loadManualExtraction();
    showToast(state==='deferred'?'已设为暂不整理 · 原始档案保持不变':'已放回可选来源');
  }catch(e){if(isRequestCancelled(e))return;showToast(e.message||'会话提炼状态更新失败')}
}
document.addEventListener('click',e=>{const defer=e.target.closest?.('[data-defer-session]'),restore=e.target.closest?.('[data-restore-session]');if(defer){e.preventDefault();changeExtractionSessionState(defer.dataset.deferSession,'deferred')}else if(restore){e.preventDefault();changeExtractionSessionState(restore.dataset.restoreSession,'pending')}});
async function showManualPackage(id){try{const d=await api('/api/memory/manual-extraction/packages/'+encodeURIComponent(id));let dialog=$('#manualPackageDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='manualPackageDialog';dialog.className='wide-dialog';document.body.append(dialog)}dialog.innerHTML=`<div class="dialog-head"><div><small>${esc(d.package_id)}</small><h2>提炼包内容</h2></div><button class="icon-button" aria-label="关闭">×</button></div><pre class="candidate-diff manual-package-content">${esc(d.content)}</pre>`;dialog.querySelector('button').onclick=()=>dialog.close();dialog.showModal()}catch(e){if(isRequestCancelled(e))return;showToast(e.message)}}
async function importManualPayload(text){try{const payload=typeof text==='string'?JSON.parse(text):text,d=await apiPost('/api/memory/manual-extraction/import',{payload});await Promise.all([loadMemoryCandidates(),loadManualExtraction()]);showToast(`已导入 ${d.imported} 条候选记忆`);const button=document.createElement('button');button.className='copy-button enter-review';button.textContent='进入审核';button.onclick=()=>{backToSuggestionList();suggestionView.tab='pending';suggestionView.filter='all';suggestionView.page=0;renderCandidateLists();$('#pendingMemoryList [data-candidate]')?.click()};$('#manualExtraction .manual-next')?.remove();$('#externalManualWorkbench .manual-actions').append(button)}catch(err){showToast(err.message||'提炼结果校验失败')}}
