    const body=$('#pendingMemoryDetail .candidate-body');if(body){body.classList.add('candidate-markdown','suggestion-full-content');body.innerHTML=renderSafeMarkdown(candidateBodyText(c.content));body.setAttribute('tabindex','0');body.setAttribute('aria-label','建议完整正文')}
