  if(refreshing){$('#pendingMemoryDetail').insertAdjacentHTML('afterbegin','<p class="detail-refresh-note" role="status">已显示这条建议，正在核对最新版本；核对完成后可操作。</p>');$('#pendingMemoryDetail').querySelectorAll('.candidate-actions button, #refreshCandidateDiff').forEach(button=>button.disabled=true)}
  if(c.status==='reorganized')$('#pendingMemoryDetail').insertAdjacentHTML('afterbegin',`<p class="detail-refresh-note" role="status">${c.reorganization?.outcome==='unchanged_verified'?'目标已包含当前结果，读取与字节一致性已核验。':'已产生关联的新待审核建议；这条旧建议作为历史保留。'} 正式写入仍需用户确认。</p>`);
  const roles=candidateRoleLabels(c);if(roles.length)$('#pendingMemoryDetail .candidate-technical')?.insertAdjacentHTML('beforeend',`<p class="candidate-source-roles"><b>来源标注：${roles.map(esc).join('、')}</b><span>这些是整理方对原文角色的标注，不代表界渡已独立验收。</span></p>`);
