function candidateReadingHeader(c){const id=candidateIdentity(c),status=c.status==='approved_staging'&&c.write_reverted_at?'已撤销写入':['pending','approved_staging'].includes(c.status)?(c.readiness?.state==='needs_reorganization'?candidateRenewalLabel(c):c.readiness?.state==='reviewable'?'待核对':'状态未确认'):candidateStatusText(c);return `<div class="candidate-head"><div><span class="suggestion-identity">${id.project?'项目':'资料'} · ${esc(id.label)}</span><h3>${esc(candidateReadableTitle(c))}</h3></div><span class="memory-state">${esc(status)}</span></div><dl class="candidate-reading-meta"><dt>${c.status==='written'?'已保存到':'拟保存到'}</dt><dd>${esc(c.provenance?.target_path||'尚未确定保存位置')}</dd><dt>建议生成于</dt><dd>${esc(formatTime(c.created_at))}</dd></dl>`}
function candidateTechnicalDetails(c){return `<details class="candidate-technical"><summary>来源与整理记录</summary><p>整理时记录的标题：${esc(c.title)}</p><pre class="candidate-evidence">${esc(JSON.stringify({candidate_id:c.candidate_id,type:c.type,provider:c.provider,submission:c.submission,provenance:c.provenance,evidence:c.evidence},null,2))}</pre></details>`}
