function openProjectEditor(){projectDiffToken=null;$('#projectEditTitle').textContent=`编辑 ${memoryProject.project}`;$('#projectEditContent').value=memoryProject.current_state;$('#projectDiff').hidden=true;$('#confirmProjectSave').disabled=true;$('#projectEditDialog').showModal()}
$('#previewProjectDiff').addEventListener('click',async()=>{try{const d=await apiPost('/api/memory/projects/'+encodeURIComponent(memoryProject.project)+'/preview',{content:$('#projectEditContent').value});projectDiffToken=d.token;$('#projectDiff').hidden=false;$('#projectDiff').textContent=d.changed?d.diff:'没有内容变化';$('#confirmProjectSave').disabled=!d.changed}catch(e){if(isRequestCancelled(e))return;showToast('Diff生成失败')}});
$('#confirmProjectSave').addEventListener('click',async()=>{if(!projectDiffToken)return;try{await apiPost('/api/memory/projects/'+encodeURIComponent(memoryProject.project)+'/confirm',{token:projectDiffToken});$('#projectEditDialog').close();memoryProject=null;await loadMemoryHub();showToast('已备份并保存项目状态')}catch(e){if(isRequestCancelled(e))return;showToast('保存失败，请重新预览Diff')}});
async function runMemoryTest(){
  const q=queryInput.value.trim();if(!q)return queryInput.focus();const box=$('#memoryTestResult');setQueryBusy(true);setQueryPanelState('answer','正在测试');box.classList.add('is-empty');box.innerHTML='<div class="memory-test-empty"><span>正在判断需要读取的记忆</span><p>高层正式知识不足时才会继续检索历史</p></div>';
  try{const d=await api('/api/memory/test?q='+encodeURIComponent(q)),raw=d.raw_message,evidence=[...(d.results||[])];box.classList.remove('is-empty');const projectEvidence=d.project?`<article><b>${esc(d.project.project)} · ${esc(d.project.status)}</b><span>${esc(d.project.source)}</span><p>${esc(d.project.summary)}</p></article>`:'';const resultEvidence=evidence.slice(0,5).map(x=>`<article><b>${esc(x.document_title)} / ${esc(String(x.section_title).replace(/^MESSAGE\s+/,'原始消息 '))}</b><span>${esc(x.message_id?`原始消息 ${x.message_id} · ${x.role}`:x.source_path)}</span><p>${esc(x.content.slice(0,420))}</p></article>`).join('');const rawEvidence=raw?`<article><b>原始消息 ${esc(raw.message_id)} · ${esc(raw.role)}</b><span>${esc(raw.source)}</span><p>${esc(raw.content)}</p></article>`:'';box.innerHTML=`<article class="memory-answer"><span>回答</span><p>${esc(d.answer)}</p></article><details class="memory-chain-details"><summary>查看本次记忆链 <small>总耗时 ${esc(d.timings.total)} ms</small></summary><div class="chain-steps">${d.calls.map(x=>`<div class="chain-step ${x.status==='成功'?'ok':x.status==='失败'?'bad':'skip'}"><i></i><div><b>${esc(memoryCallNames[x.interface]||x.interface)}</b><small>${esc(x.status)}${x.hit?` · ${esc(x.hit)}`:''}${x.hit_count!=null?` · ${x.hit_count}条`:''}${x.duration_ms!=null?` · ${esc(x.duration_ms)} ms`:''}</small></div></div>`).join('')}</div><div class="memory-source-summary">使用来源：${(d.sources||[]).map(esc).join('、')||'无额外文件'}<br>项目状态：${d.project?'已调用':'未调用'} · 混合检索：${d.calls.some(x=>x.interface==='search_memory'&&x.status==='成功')?'已调用':'未调用'} · L0：${raw?'已进入':'未进入'}</div></details><details class="memory-evidence-details"><summary>查看检索证据</summary><div class="chain-hit">${projectEvidence}${resultEvidence}${rawEvidence||(!projectEvidence&&!resultEvidence?'<p>本次由正式Core直接回答，没有下探检索证据。</p>':'')}</div></details>`;setQueryPanelState('answer',`完成 · 链路 ${d.timings.total} ms`)}catch(e){if(isRequestCancelled(e))return;box.classList.add('is-empty');box.innerHTML=`<div class="memory-test-empty"><span>链路未完成</span><p>${esc(e.message)}</p></div>`;setQueryPanelState('answer','测试失败')}finally{setQueryBusy(false)}
}

window.addEventListener('resize',()=>{resizeVectorCanvas();graphChart?.resize()});
applyPrefs();(async()=>{try{workspaceRuntime=await api('/api/health',{ttl:0,force:true,scope:'health'});let installNotice;try{installNotice=await api('/api/update-notice',{ttl:0,force:true,scope:'health'})}catch{installNotice={state:'unconfirmed',message:'安装状态暂时无法读取，请稍后重试。'}}if(installNotice.state==='ready'&&installNotice.show_first_run)await showFirstRunGuide(workspaceRuntime,{installedFresh:true});else if(installNotice.state==='not_installed')await showFirstRunGuide(workspaceRuntime);await window.jieduUpdateNotice?.initialize(workspaceRuntime,installNotice);await loadProtectionStatus({quiet:true});const requestedPage=new URLSearchParams(location.search).get('page'),availablePage=requestedPage&&document.getElementById(requestedPage)&&document.querySelector(`.sidebar nav button[data-page="${CSS.escape(requestedPage)}"]`)?requestedPage:null;switchPage(workspaceRuntime.workspace_ready?(availablePage||sessionStorage.getItem('jiedu.activePage')||'overview'):'workspace');document.body.classList.remove('first-run-pending')}catch(error){if(isRequestCancelled(error))return;$('#status').textContent='连接失败';showToast('服务暂时不可用，请检查界渡是否运行');document.body.classList.remove('first-run-pending')}})();
let healthTimer=null,healthBusy=false;
async function refreshHealth(){if(document.hidden||healthBusy)return;healthBusy=true;try{const d=await api('/api/health?t='+Date.now(),{ttl:0,force:true,scope:'health'}),banner=$('#testEnvironmentBanner');if(banner)banner.hidden=d.environment!=='isolated_test';document.body.classList.toggle('isolated-test',d.environment==='isolated_test');$('#status').textContent=d.status==='ready'?'界渡已运行':'需要检查'}catch{$('#status').textContent='连接中断'}finally{healthBusy=false}}
function scheduleHealth(){clearInterval(healthTimer);if(!document.hidden)healthTimer=setInterval(refreshHealth,30000)}
document.addEventListener('visibilitychange',()=>{scheduleHealth();if(!document.hidden)refreshHealth()});scheduleHealth();refreshHealth();

function renderArchiveConnection(client){const a=client.archive||{},policy=clientPolicyValue(client,'evidence','raw_archive'),doubao=a.source_key==='doubao_work',independent=['codex_local','hermes_local'].includes(client.source_adapter?.adapter_id);return `<section class="session-read-panel"><h4>${doubao?'豆包本机候选采集':'当前连接的聊天提交'}</h4>${!a.bound?'<label>产品来源<select id="archiveSourceKey"><option value="">请选择实际产品</option><option value="doubao_work">豆包工作版</option><option value="chatgpt_web">ChatGPT Web</option><option value="codex">Codex</option><option value="hermes">Hermes</option><option value="custom">其他产品</option></select></label><label>其他产品名称<input id="archiveProductName" placeholder="例如：Claude"></label><button type="button" id="bindArchiveSource">登记此连接的推送来源</button>':''}<p>追加权限：${esc(clientDecisionLabels[policy]||policy)} · ${esc(a.collection_status||'尚未绑定归档来源')}</p><p>${doubao?'候选档案位置':'显式提交位置'}：${esc(a.archive_path||'需要选择产品来源')}</p><p>覆盖：${esc(a.history_coverage||'未知')} · 最近一次：${a.last_archived_at?formatTime(a.last_archived_at):'尚无记录'}</p><p>${doubao?'豆包采集已暂停；保留已有候选与档案。':independent?'这张卡只统计当前 MCP 连接主动提交的聊天；本机自动采集器独立运行，状态见左侧“自动归档状态”。知识读取成功不代表这条连接提交了聊天。':'这张卡只统计当前 MCP 连接主动提交的聊天。知识读取成功不代表已经取得源端聊天或自动归档。'}</p></section>`}







